     1→import type { IconData } from "@/components/ui/icon-picker";
     2→import type { BreadcrumbStackItem, BreadcrumbMeta } from "./breadcrumb-builder";
     3→import { createBreadcrumbItem } from "./breadcrumb-stack";
     4→
     5→export interface BreadcrumbNodeDescriptor {
     6→  id?: string;
     7→  descriptorId?: string;
     8→  label: string;
     9→  href: string;
    10→  icon?: IconData;
    11→  meta?: BreadcrumbMeta;
    12→  sourceNodeId?: string;
    13→  parentNodeId?: string;
    14→}
    15→
    16→export interface ResolvedNavigationState<TValue> {
    17→  value: TValue;
    18→  breadcrumbStack: BreadcrumbStackItem[];
    19→}
    20→
    21→export function createBreadcrumbNode(
    22→  descriptor: BreadcrumbNodeDescriptor
    23→): BreadcrumbStackItem {
    24→  return createBreadcrumbItem({
    25→    id: descriptor.id ?? descriptor.href,
    26→    label: descriptor.label,
    27→    href: descriptor.href,
    28→    icon: descriptor.icon,
    29→    meta: descriptor.meta,
    30→    sourceNodeId: descriptor.sourceNodeId,
    31→    parentNodeId: descriptor.parentNodeId,
    32→    descriptorId: descriptor.descriptorId,
    33→  });
    34→}
    35→
    36→export function buildBreadcrumbStack(
    37→  descriptors: BreadcrumbNodeDescriptor[]
    38→): BreadcrumbStackItem[] {
    39→  return descriptors.map(createBreadcrumbNode);
    40→}
    41→
    42→export function resolveNavigationState<TValue>(
    43→  value: TValue,
    44→  descriptors: BreadcrumbNodeDescriptor[]
    45→): ResolvedNavigationState<TValue> {
    46→  return {
    47→    value,
    48→    breadcrumbStack: buildBreadcrumbStack(descriptors),
    49→  };
    50→}
