     1→// apps/desktop/src/navigation/breadcrumb-builder.ts
     2→import { registry, humanize } from "./route-registry";
     3→import type { RouteEntry } from "./route-compiler";
     4→import type { IconData } from "@/components/ui/icon-picker";
     5→import type { WorkspaceSection } from "./navigation-meta";
     6→
     7→// ─── Types ──────────────────────────────────────────────────────────────────
     8→
     9→export interface NavigateHeaders {
    10→  label?: string;
    11→  icon?: IconData;
    12→  id?: string;
    13→  sourceNodeId?: string;
    14→  parentNodeId?: string;
    15→  meta?: BreadcrumbMeta;
    16→}
    17→
    18→export interface BreadcrumbMeta {
    19→  workspaceId?: string;
    20→  section?: WorkspaceSection;
    21→  routePath?: string;
    22→  pageSlug?: string;
    23→  agentId?: string;
    24→  executorType?: string;
    25→  webId?: string;
    26→  url?: string;
    27→  blockId?: string;
    28→}
    29→
    30→export interface BreadcrumbStackItem {
    31→  id: string;
    32→  label: string;
    33→  href: string;
    34→  icon?: IconData;
    35→  descriptorId?: string;
    36→  pattern?: string;
    37→  sourceNodeId?: string;
    38→  parentNodeId?: string;
    39→  meta?: BreadcrumbMeta;
    40→}
    41→
    42→// ─── Cold Start Builder ─────────────────────────────────────────────────────
    43→
    44→export function buildColdStartBreadcrumb(url: string, headers?: NavigateHeaders): BreadcrumbStackItem[] {
    45→  const match = registry.match(url);
    46→  if (!match) return [];
    47→
    48→  const chain: BreadcrumbStackItem[] = [];
    49→
    50→  // 1. Path prefix ancestors
    51→  for (const ancestorPattern of deriveAncestorsFromPrefix(match.pattern)) {
    52→    const ancestorEntry = registry.getEntry(ancestorPattern)!;
    53→    const ancestorParams = pickMatchingParams(ancestorPattern, match.params);
    54→    const item = buildBreadcrumbItem(ancestorEntry, ancestorParams);
    55→
    56→    // Annotate workspace root for buildDerivedHeader to detect
    57→    if (ancestorPattern === "/workspace/:workspaceId" && ancestorParams.workspaceId) {
    58→      item.descriptorId = "workspace";
    59→      item.meta = { ...item.meta, workspaceId: ancestorParams.workspaceId };
    60→    }
    61→
    62→    chain.push(item);
    63→  }
    64→
    65→  // 2. Rest param intermediate levels
    66→  const restParam = registry.getRestParam(match.pattern);
    67→  if (restParam && match.params[restParam]?.includes("/")) {
    68→    const segments = match.params[restParam].split("/");
    69→    for (let i = 1; i < segments.length; i++) {
    70→      const prefix = segments.slice(0, i).join("/");
    71→      const lastSegment = segments[i - 1];
    72→      chain.push(buildBreadcrumbItem(
    73→        match.entry,
    74→        { ...match.params, [restParam]: prefix },
    75→        { label: humanize(lastSegment) },
    76→      ));
    77→    }
    78→  }
    79→
    80→  // 3. Current node (headers can override label/icon)
    81→  chain.push(buildBreadcrumbItem(match.entry, match.params, headers));
    82→
    83→  return chain;
    84→}
    85→
    86→// ─── Helpers ────────────────────────────────────────────────────────────────
    87→
    88→export function deriveAncestorsFromPrefix(pattern: string): string[] {
    89→  const segments = pattern.split("/").filter(Boolean);
    90→  const ancestors: string[] = [];
    91→
    92→  for (let i = segments.length - 1; i > 0; i--) {
    93→    const candidate = "/" + segments.slice(0, i).join("/");
    94→    const entry = registry.getEntry(candidate);
    95→    if (entry && !entry.isContainer) {
    96→      ancestors.unshift(candidate);
    97→    }
    98→  }
    99→  return ancestors;
   100→}
   101→
   102→export function pickMatchingParams(
   103→  targetPattern: string,
   104→  allParams: Record<string, string>,
   105→): Record<string, string> {
   106→  const paramNames = registry.getParamNames(targetPattern);
   107→  const result: Record<string, string> = {};
   108→  for (const name of paramNames) {
   109→    if (allParams[name] !== undefined) {
   110→      result[name] = allParams[name];
   111→    }
   112→  }
   113→  return result;
   114→}
   115→
   116→export function buildBreadcrumbItem(
   117→  entry: RouteEntry,
   118→  params: Record<string, string>,
   119→  headers?: NavigateHeaders,
   120→): BreadcrumbStackItem {
   121→  const href = registry.build(entry.pattern, params);
   122→  const icon = headers?.icon ?? (typeof entry.icon === "function" ? entry.icon(params) : entry.icon);
   123→  const title = typeof entry.title === "function" ? entry.title(params) : entry.title;
   124→
   125→  return {
   126→    id: headers?.id ?? href,
   127→    label: headers?.label ?? title,
   128→    icon,
   129→    pattern: entry.pattern,
   130→    href,
   131→    sourceNodeId: headers?.sourceNodeId,
   132→    parentNodeId: headers?.parentNodeId,
   133→    meta: headers?.meta,
   134→  };
   135→}
