    16→// ─── Hook 1: useTabList ─────────────────────────────────────────────────────
    17→// Returns the tab view model list. Only re-renders when the tabs array changes.
    18→
    19→export function useTabList(): TabViewModel[] {
    20→  const rawTabs = useTabStore((state) => state.tabs);
    21→  return useMemo(() => rawTabs.map(getTabViewModel), [rawTabs]);
    22→}
    23→
    24→// ─── Hook 2: useActiveTabState ──────────────────────────────────────────────
    25→// Returns reactive state about the active tab. Re-renders when active tab changes.
    26→
    27→export interface ActiveTabState {
    28→  activeTabId: string | null;
    29→  activeTab: TabViewModel | null;
    30→  canGoBack: boolean;
    31→  canGoForward: boolean;
    32→  currentUrl: string | null;
    33→  currentNavigationState: TabNavigationState | null;
    34→}
    35→
    36→export function useActiveTabState(): ActiveTabState {
    37→  const activeTabId = useTabStore((state) => state.activeTabId);
    38→  const activeTabRaw = useTabStore((state) =>
    39→    state.tabs.find((tab) => tab.id === state.activeTabId) ?? null
    40→  );
    41→  const canGoBackFn = useTabStore((state) => state.canGoBack);
    42→  const canGoForwardFn = useTabStore((state) => state.canGoForward);
    43→  const getCurrentUrl = useTabStore((state) => state.getCurrentUrl);
    44→  const getCurrentNavigationState = useTabStore(
    45→    (state) => state.getCurrentNavigationState
    46→  );
    47→
    48→  const activeTab = useMemo(
    49→    () => (activeTabRaw ? getTabViewModel(activeTabRaw) : null),
    50→    [activeTabRaw]
    51→  );
    52→
    53→  const canGoBack = activeTabId ? canGoBackFn(activeTabId) : false;
    54→  const canGoForward = activeTabId ? canGoForwardFn(activeTabId) : false;
    55→  const currentUrl = activeTabId ? getCurrentUrl(activeTabId) : null;
    56→  const currentNavigationState = activeTabId
    57→    ? getCurrentNavigationState(activeTabId)
    58→    : null;
    59→
    60→  return useMemo(
    61→    () => ({
    62→      activeTabId,
    63→      activeTab,
    64→      canGoBack,
    65→      canGoForward,
    66→      currentUrl,
    67→      currentNavigationState,
    68→    }),
    69→    [activeTabId, activeTab, canGoBack, canGoForward, currentUrl, currentNavigationState]
    70→  );
    71→}
